  function t(key) { return data[key] != null ? data[key] : (dataMap.en[key] != null ? dataMap.en[key] : ''); }
  function setText(id, key) { const el = document.getElementById(id); if (el) el.textContent = t(key); }
  function setHtml(id, html) { const el = document.getElementById(id); if (el) el.innerHTML = html; }
  function getFlag(locale) { return 'https://flagcdn.com/w20/' + ((localeNames[locale] && localeNames[locale].flag) || 'us') + '.png'; }
  function updateLinks() {
    const regex = /^\/(?:(ko|en|ja|zh-cn|zh-tw|es|fr|de|pt-br|hi|ar|ru|id|tr|it|vi|th|nl)\/)?(roulette|luckydraw|ladder|team-generator|coinflip|dice)\/?$/i;
    document.querySelectorAll('a[href]').forEach((a) => {
      const href = a.getAttribute('href');
      if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:') || href.startsWith('javascript:')) return;
      const url = new URL(href, window.location.origin);
      if (url.origin !== window.location.origin || !url.pathname.startsWith('/')) return;
      const m = url.pathname.match(regex);
      if (m) {
        const tool = m[2].toLowerCase();
        url.pathname = state.locale === 'ko' ? '/' + tool + '/' : '/' + state.locale + '/' + tool + '/';
        if (tool === 'roulette') url.pathname = state.locale === 'ko' ? '/' : '/' + state.locale + '/';
        url.searchParams.delete('lang');
        a.setAttribute('href', url.pathname + url.search + url.hash);
      }
    });
  }
  function renderLanguageList(query, listId) {
    const list = document.getElementById(listId);
    if (!list) return;
    const q = String(query || '').trim().toLowerCase();
    list.innerHTML = '';
    supported.filter((locale) => {
      if (!q) return true;
      const meta = localeNames[locale] || { native: locale, en: locale };
      return meta.native.toLowerCase().includes(q) || meta.en.toLowerCase().includes(q) || locale.includes(q);
    }).forEach((locale) => {
      const meta = localeNames[locale] || { native: locale, en: locale, flag: 'us' };
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'w-full flex items-center gap-2 rounded-lg px-2.5 py-2 text-left hover:bg-slate-50';
      btn.innerHTML = '<img src="' + getFlag(locale) + '" alt="' + meta.en + '" class="w-4 h-3 rounded-[2px] object-cover border border-slate-200"><span class="text-xs font-medium text-slate-700">' + meta.native + '</span><span class="ml-auto text-[11px] text-slate-400">' + meta.en + '</span>';
      btn.addEventListener('click', function () { setLocale(locale); });
      list.appendChild(btn);
    });
  }
  function setLocale(next) {
    if (!supported.includes(next)) return;
    try { window.localStorage.setItem('rlt-lang', next); } catch (e) {}
    const url = new URL(window.location.href);
    const nextPath = next === 'ko' ? '/team-generator/' : '/' + next + '/team-generator/';
    window.location.assign(nextPath + url.hash);
  }
